 const complete=code=>{
  clearTimeout(deadline);
  const error=Buffer.concat(stderr).toString('utf8');stderr=[];stderrBytes=0;stdoutBytes=0;
  if(error){if(code)diagnostic(error,mode);else process.stderr.write(error);}
