  execute(args){
   if(pending)throw Error('PSC1_WATCH_CONCURRENT_REQUEST');
   if(!child)start();
   return new Promise(resolve=>{
    pending={id:++serial,resolve};deadline=setTimeout(()=>{diagnostic('PSC1_WATCH_REQUEST_TIMEOUT',mode);stop('SIGKILL');},240000);
